// Define the migration from V1 to V2
impl From<PluginConfigV1> for PluginConfigV2 {
    fn from(v1: PluginConfigV1) -> Self {
        Self {
            plugin_name: v1.name,
            schema_version: v1.version,
            is_active: v1.enabled,
            description: None, // Default value for new field
        }
    }
}

// Define the final domain type, which can be migrated to from any previous version
#[derive(Clone, Debug, Versioned, PartialEq, Eq)]
#[versioned(
    mode = "infallible",
    chain(PluginConfigV1, PluginConfigV2),
)]
pub struct CurrentPluginConfig {
    pub plugin_name: String,
    pub schema_version: u32,
    pub is_active: bool,
    pub description: Option<String>,
}

// Migration from V2 to CurrentPluginConfig (if CurrentPluginConfig is identical to V2, this is trivial)
impl From<PluginConfigV2> for CurrentPluginConfig {
    fn from(v2: PluginConfigV2) -> Self {
        Self {
            plugin_name: v2.plugin_name,
            schema_version: v2.schema_version,
            is_active: v2.is_active,
            description: v2.description,
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Simulate loading an old V1 blob
    let old_v1_json = r#"{"_version":1,"name":"MyOldPlugin","version":1,"enabled":true}"#;
    let versioned_config: CurrentPluginConfig = serde_json::from_str(old_v1_json)?;

    println!("Migrated V1 config: {:?}", versioned_config);
    assert_eq!(versioned_config.plugin_name, "MyOldPlugin");
    assert_eq!(versioned_config.schema_version, 1);
    assert_eq!(versioned_config.is_active, true);
    assert_eq!(versioned_config.description, None);

    // Simulate loading a V2 blob
    let v2_json = r#"{"_version":2,"plugin_name":"MyNewPlugin","schema_version":2,"is_active":false,"description":"A new plugin"}"#;
    let versioned_config_v2: CurrentPluginConfig = serde_json::from_str(v2_json)?;

    println!("Migrated V2 config: {:?}", versioned_config_v2);
    assert_eq!(versioned_config_v2.plugin_name, "MyNewPlugin");
    assert_eq!(versioned_config_v2.schema_version, 2);
    assert_eq!(versioned_config_v2.is_active, false);
    assert_eq!(versioned_config_v2.description, Some("A new plugin".to_string()));

    Ok(())
}
