pub struct PluginConfig {
    pub name: String,
    pub version: String,
    pub enabled: bool,
    pub settings: serde_json::Value,
}

fn main() {
    let schema = schema_for!(PluginConfig);
    println!("{}", serde_json::to_string_pretty(&schema).unwrap());
}
```

