79	/// Materialize a deterministic initial live state from a plugin schema.
80	///
81	/// This is the schema-side bootstrap for D-Bus projection creation. It never
82	/// queries a plugin backend and never invents data outside the contract:
83	/// field defaults win, then examples, then an empty value matching the field
84	/// type. The MutationEngine writes this once when no projection exists yet;
85	/// later mutations replace it through the normal `/dev/shm/opdbus/projections`
86	/// write door.
87	pub(crate) fn materialize_state_from_schema(schema: &PluginSchema) -> Value {
88	    if let Some(example) = &schema.example {
89	        return example.clone();
90	    }
91	
92	    let mut state = simd_json::value::owned::Object::new();
93	    let mut fields = schema.fields.iter().collect::<Vec<_>>();
94	    fields.sort_by_key(|(a, _)| *a);
95	
96	    for (name, field) in fields {
97	        state.insert(name.clone(), materialize_field(field));
98	    }
99	
100	    Value::Object(Box::new(state))
101	}
102	
103	fn materialize_field(field: &FieldSchema) -> Value {
104	    if let Some(value) = &field.default {
105	        return value.clone();
106	    }
107	    if let Some(value) = &field.example {
108	        return value.clone();
109	    }
110	
111	    materialize_field_type(&field.field_type)
112	}
113	
114	fn materialize_field_type(field_type: &FieldType) -> Value {
115	    match field_type {
116	        FieldType::String => json!(""),
117	        FieldType::Integer => json!(0),
118	        FieldType::Float => json!(0.0),
119	        FieldType::Boolean => json!(false),
120	        FieldType::Array(_) => json!([]),
121	        FieldType::Object(fields) => {
122	            let mut object = simd_json::value::owned::Object::new();
123	            let mut fields = fields.iter().collect::<Vec<_>>();
124	            fields.sort_by_key(|(a, _)| *a);
125	            for (name, field) in fields {
126	                object.insert(name.clone(), materialize_field(field));
127	            }
128	            Value::Object(Box::new(object))
129	        }
130	        FieldType::Enum(values) => values
131	            .first()
132	            .map(|value| json!(value))
133	            .unwrap_or_else(|| json!(null)),
134	        FieldType::OneOf(types) => types
135	            .first()
136	            .map(materialize_field_type)
137	            .unwrap_or_else(|| json!(null)),
138	        FieldType::Any => json!(null),
139	    }
140	}
141	
142	/// Format a plugin's live state into a `PluginSchema`.
143	///
144	/// This is a *formatter*, not a schema authority — nothing here is indexed. The
145	/// plugin's live state (its `*State` struct) is the single source
146	/// of truth; field types are inferred from that state, so the schema can never
147	/// drift from what the plugin actually reports. To add a field, add it to the
148	/// plugin state — never hand-write a field definition.
149	pub(crate) fn schema_from_state(
150	    name: &str,
151	    category: &str,
152	    version: &str,
153	    description: &str,
154	    state: &Value,
155	) -> PluginSchema {
156	    use simd_json::prelude::*;
157	
158	    let mut builder = PluginSchema::builder(name)
159	        .version(version)
160	        .category(category)
161	        .description(description);
162	
163	    if let Some(obj) = state.as_object() {
164	        for (key, value) in obj.iter() {
165	            builder = builder.field(&key.to_string(), field_from_value(value));
166	        }
167	    }
168	
169	    builder.example(state.clone()).build()
170	}
171	
172	/// Infer a `FieldSchema` (type + example) from a live state value.
173	pub(crate) fn field_from_value(value: &Value) -> FieldSchema {
174	    FieldSchema {
175	        field_type: infer_field_type(value),
176	        required: false,
177	        description: String::new(),
178	        default: None,
179	        example: Some(value.clone()),
180	        constraints: Vec::new(),
181	        read_only: false,
182	        read_only_when: None,
183	    }
184	}
185	
186	/// Infer a `FieldType` from a live state value, recursing into arrays/objects.
187	pub(crate) fn infer_field_type(value: &Value) -> FieldType {
188	    use simd_json::prelude::*;
189	
190	    if value.is_null() {
191	        FieldType::Any
192	    } else if value.as_bool().is_some() {
193	        FieldType::Boolean
194	    } else if value.as_i64().is_some() || value.as_u64().is_some() {
195	        FieldType::Integer
196	    } else if value.as_f64().is_some() {
197	        FieldType::Float
198	    } else if value.as_str().is_some() {
199	        FieldType::String
200	    } else if let Some(arr) = value.as_array() {
201	        let inner = arr.first().map(infer_field_type).unwrap_or(FieldType::Any);
202	        FieldType::Array(Box::new(inner))
203	    } else if let Some(obj) = value.as_object() {
204	        let fields = obj
205	            .iter()
206	            .map(|(k, v)| (k.to_string(), field_from_value(v)))
207	            .collect();
208	        FieldType::Object(fields)
209	    } else {
210	        FieldType::Any
211	    }
212	}
213	
214	pub(crate) fn any_field(required: bool, description: &str, default: Option<Value>) -> FieldSchema {
215	    FieldSchema {
216	        field_type: FieldType::Any,
217	        required,
218	        description: description.to_string(),
219	        default,
220	        example: None,
221	        constraints: Vec::new(),
222	        read_only: false,
223	        read_only_when: None,
224	    }
225	}
226	
227	pub(crate) fn cap_method(
228	    name: &str,
229	    side_effect: SideEffect,
230	    idempotent: bool,
231	    required_capability: &str,
232	    subid: &str,
233	) -> MethodDecl {
234	    MethodDecl {
235	        name: name.to_string(),
236	        args: json!({"type": "object", "additionalProperties": true}),
237	        returns: Some(json!({"type": "object", "additionalProperties": true})),
238	        side_effect,
239	        idempotent,
240	        required_capability: Some(required_capability.to_string()),
241	        subid: subid.to_string(),
242	    }
243	}
244	
245	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize, schemars::JsonSchema)]
246	pub struct EmptyInput {}
247	
248	/// Create a MethodDecl from a schemars-typed input struct.
249	///
250	/// This is the canonical pattern for all plugins: define method inputs as
251	/// Rust structs with `#[derive(schemars::JsonSchema)]`, then use this function
252	/// to generate typed method declarations. The resulting schema drives D-Bus method
253	/// validation and gRPC proto generation.
254	///
255	/// For methods with typed outputs, use `method_decl_from_schemars_with_output`.
256	/// For methods with no meaningful return (just success/failure), use `AckOutput`.
257	#[deprecated(
258	    since = "0.2.0",
259	    note = "Use method_decl_from_schemars_with_output for typed returns"
260	)]
261	pub fn method_decl_from_schemars<Input: schemars::JsonSchema>(
262	    name: &str,
263	    side_effect: SideEffect,
264	    idempotent: bool,
265	    required_capability: &str,
266	    subid: &str,
267	) -> MethodDecl {
268	    method_decl_from_schemars_with_output::<Input, AckOutput>(
269	        name,
270	        side_effect,
271	        idempotent,
272	        required_capability,
273	        subid,
274	    )
275	}
276	
277	/// Dual-generic helper that generates method declarations with typed input AND output schemas.
278	/// The returns schema is derived from `Output` via schemars - NO hardcoded `{"type": "object"}`.
279	pub fn method_decl_from_schemars_with_output<
280	    Input: schemars::JsonSchema,
281	    Output: schemars::JsonSchema,
282	>(
283	    name: &str,
284	    side_effect: SideEffect,
285	    idempotent: bool,
286	    required_capability: &str,
287	    subid: &str,
288	) -> MethodDecl {
289	    // Generate input schema
290	    let serde_input_schema = serde_json::to_value(schemars::schema_for!(Input)).unwrap();
291	    let input_bytes = serde_json::to_vec(&serde_input_schema).unwrap();
292	    let mut input_bytes = input_bytes;
293	    let args = simd_json::to_owned_value(&mut input_bytes).unwrap();
294	
295	    // Generate output schema
296	    let serde_output_schema = serde_json::to_value(schemars::schema_for!(Output)).unwrap();
297	    let output_bytes = serde_json::to_vec(&serde_output_schema).unwrap();
298	    let mut output_bytes = output_bytes;
299	    let returns = simd_json::to_owned_value(&mut output_bytes).unwrap();
300	
301	    MethodDecl {
302	        name: name.to_string(),
303	        args,
304	        returns: Some(returns),
305	        side_effect,
306	        idempotent,
307	        required_capability: Some(required_capability.to_string()),
308	        subid: subid.to_string(),
309	    }
310	}
311	
312	/// Standard acknowledgment response for methods that only need success/failure.
313	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
314	pub struct AckOutput {
315	    pub success: bool,
316	}
317	
318	pub(crate) fn simple_schema(
319	    name: &str,
320	    description: &str,
321	    dependencies: &[&str],
322	    fields: Vec<(&str, FieldSchema)>,
323	) -> PluginSchema {
324	    let mut builder = PluginSchema::builder(name)
325	        .version("1.0.0")
326	        .description(description);
327	    for dep in dependencies {
328	        builder = builder.dependency(dep);
329	    }
330	    for (field_name, schema) in fields {
331	        builder = builder.field(field_name, schema);
332	    }
333	    builder.build()
334	}
335	
336	#[cfg(test)]
337	mod tests {
338	    use super::*;
339	    use std::collections::HashMap;
340	
341	    fn field(field_type: FieldType, default: Option<Value>, example: Option<Value>) -> FieldSchema {
342	        FieldSchema {
343	            field_type,
344	            required: false,
345	            description: String::new(),
346	            default,
347	            example,
348	            constraints: Vec::new(),
349	            read_only: false,
350	            read_only_when: None,
351	        }
352	    }
353	
354	    #[test]
355	    fn materializes_seed_state_from_schema_defaults_examples_and_types() {
356	        let schema = PluginSchema::builder("example")
357	            .field(
358	                "enabled",
359	                field(FieldType::Boolean, Some(json!(true)), Some(json!(false))),
360	            )
361	            .field("label", field(FieldType::String, None, Some(json!("demo"))))
362	            .field(
363	                "mode",
364	                field(
365	                    FieldType::Enum(vec!["active".to_string(), "passive".to_string()]),
366	                    None,
367	                    None,
368	                ),
369	            )
370	            .field(
371	                "choice",
372	                field(
373	                    FieldType::OneOf(vec![FieldType::Integer, FieldType::String]),
374	                    None,
375	                    None,
376	                ),
377	            )
378	            .field(
379	                "nested",
380	                field(
381	                    FieldType::Object(HashMap::from([(
382	                        "count".to_string(),
383	                        field(FieldType::Integer, None, None),
384	                    )])),
385	                    None,
386	                    None,
387	                ),
388	            )
389	            .build();
390	
391	        let state = materialize_state_from_schema(&schema);
392	
393	        assert_eq!(state["enabled"], json!(true));
394	        assert_eq!(state["label"], json!("demo"));
395	        assert_eq!(state["mode"], json!("active"));
396	        assert_eq!(state["choice"], json!(0));
397	        assert_eq!(state["nested"]["count"], json!(0));
398	    }
399	}
