159	/// Matryoshka output dimensions. A 2048-dim voyage-4 vector's leading *k* entries
160	/// (256/512/1024) are themselves a valid k-dim embedding, so a collection can be
161	/// truncated to a shorter dim later **without re-vectorizing** (leading-k +
162	/// re-normalize). Every vector in one Qdrant collection must still share one dim;
163	/// 1024 is the trio default.
164	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema, PartialEq)]
165	pub enum MatryoshkaDim {
166	    #[serde(rename = "256")]
