183	    /// Numeric dimensionality.
184	    pub fn dims(&self) -> u32 {
185	        match self {
186	            MatryoshkaDim::D256 => 256,
187	            MatryoshkaDim::D512 => 512,
188	            MatryoshkaDim::D1024 => 1024,
189	            MatryoshkaDim::D2048 => 2048,
