194	/// Output precision / quantization for stored vectors. `float` (default, highest
195	/// accuracy) → `int8`/`uint8` (4× smaller) → `binary`/`ubinary` (32× smaller,
196	/// bit-packed). Qdrant stores and searches all of these natively. Changing dtype
197	/// is a precision change, **not** a re-vectorize.
198	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema, PartialEq)]
199	#[serde(rename_all = "snake_case")]
200	pub enum OutputDtype {
201	    Float,
