26	/// A configured unix-domain socket endpoint.
27	///
28	/// In the single-socket model, one shared socket (e.g.
29	/// `/run/ghostbridge/container.sock`) serves all services.  xray routes by
30	/// domain/SNI to the tonic-web gRPC bridge, which listens on this socket and
31	/// demuxes by gRPC service/method (via reflection).
32	#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
33	pub struct SocketEndpoint {
34	    /// Container/service identity (the `createunixsocket --name`). The tonic-web
35	    /// gRPC bridge demuxes by gRPC service/method via server reflection — this
36	    /// name is the routing/identity tag gemma emits into the xray config; it is
37	    /// NOT a network namespace (filesystem UDS are not netns-scoped).
38	    #[serde(default)]
39	    #[schemars(
40	        description = "Container/service identity tag the bridge routes by (createunixsocket --name)",
41	        example = &"netmaker",
42	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-name@v1")
43	    )]
44	    pub name: String,
45	    /// Filesystem path to the shared socket.
46	    #[schemars(
47	        description = "Filesystem path of the shared unix domain socket",
48	        example = &"/run/ghostbridge/container.sock",
49	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-path@v1")
50	    )]
51	    pub path: String,
52	    /// Backend TCP ports this container serves (the `createunixsocket --port`
53	    /// list, e.g. `25,465,587` for mail). Recorded metadata only — tonic-web
54	    /// distinguishes single vs multi protocol and demuxes by reflection, so the
55	    /// plugin neither opens these ports nor maps them; they describe the backend.
56	    #[serde(default)]
57	    #[schemars(
58	        description = "Backend TCP ports the container serves (metadata; tonic-web demuxes by reflection)",
59	        example = &[25u16, 465, 587],
60	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-port@v1")
61	    )]
62	    pub ports: Vec<u16>,
63	    /// Transport protocol carried over the socket.
64	    #[serde(default = "default_protocol")]
65	    #[schemars(
66	        description = "Transport protocol carried over the socket (grpc, jsonrpc, …)",
67	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-protocol@v1")
68	    )]
69	    pub protocol: String,
70	    /// Human-readable label for the shared socket.
71	    #[serde(default)]
72	    #[schemars(
73	        description = "Human-readable label for the shared socket",
74	        example = &"ghostbridge",
75	        extend("x-oscal-subid" = "mut.service.unix-socket.bind-label@v1")
