144	/// Canonical `unix_socket` schema, **derived** from the structs via schemars
145	/// (see [`super::schemars_adapter`]). `port` bounds, field descriptions (from
146	/// doc comments) and `required` flags all come from the type — the struct is
147	/// the single source of truth. The frozen hand-rolled `unix_socket_schema()`
148	/// (test-only) guards this against drift via `derived_schema_matches_hand_rolled`.
149	pub fn unix_socket_schema_derived() -> PluginSchema {
150	    let root = serde_json::to_value(schemars::schema_for!(UnixSocketState))
151	        .expect("schemars schema serializes to JSON");
152	    let mut schema = super::schemars_adapter::plugin_schema_from_json(
153	        "unix_socket",
154	        "1.0.0",
155	        "Single shared unix-domain socket for the tonic-web gRPC bridge — all services route through it, demuxed by domain/SNI at xray and by gRPC service/method at the bridge",
156	        &root,
157	    );
158	    super::common::oscal::ensure_category_metadata_fields(&mut schema);
159	    // The createunixsocket action (mut.service.unix-socket.create-socket@v1):
160	    // register a container/service on the shared container.sock. D-Bus/gRPC
161	    // method signatures derive from the schema; this subid is the OSCAL handle.
162	    schema.subids.insert(
163	        "createunixsocket".to_string(),
164	        "mut.service.unix-socket.create-socket@v1".to_string(),
165	    );
166	
167	    // Bind method - bind a socket to a path
168	    schema.methods.insert(
169	        "bind".to_string(),
170	        method_decl_from_schemars::<BindInput>(
171	            "Bind",
172	            op_state_store::SideEffect::Mutation,
173	            false,
174	            "network.write",
175	            "mut.service.unix-socket.bind@v1",
176	        ),
177	    );
178	
179	    // Listen method
180	    schema.methods.insert(
181	        "listen".to_string(),
182	        method_decl_from_schemars::<ListenInput>(
183	            "Listen",
184	            op_state_store::SideEffect::Mutation,
185	            false,
186	            "network.write",
187	            "mut.service.unix-socket.listen@v1",
188	        ),
189	    );
190	
191	    // Accept method
192	    schema.methods.insert(
193	        "accept".to_string(),
194	        method_decl_from_schemars::<AcceptInput>(
195	            "Accept",
196	            op_state_store::SideEffect::Read,
197	            true,
198	            "network.read",
199	            "obs.service.unix-socket.accept@v1",
200	        ),
201	    );
202	
203	    // Close method
204	    schema.methods.insert(
205	        "close".to_string(),
206	        method_decl_from_schemars::<CloseInput>(
207	            "Close",
208	            op_state_store::SideEffect::Mutation,
209	            false,
210	            "network.write",
211	            "mut.service.unix-socket.close@v1",
212	        ),
213	    );
214	
215	    schema
216	}
