218	pub struct UnixSocketPlugin {
219	    /// Live listeners keyed by socket path. Holding the `UnixListener` keeps the
220	    /// socket bound for the lifetime of the plugin; dropping it tears it down.
221	    active: Arc<Mutex<HashMap<String, UnixListener>>>,
222	}
223	
224	impl UnixSocketPlugin {
225	    pub fn new() -> Self {
226	        Self {
227	            active: Arc::new(Mutex::new(HashMap::new())),
228	        }
229	    }
230	
231	    /// Read this plugin's desired socket set straight from the single active
232	    /// schema catalog in shared memory (zero-copy 1:1). The catalog is keyed by
233	    /// plugin name and each entry carries the schema-declared state.
234	    fn read_desired() -> UnixSocketState {
235	        let Ok(mut bytes) = std::fs::read(SHM_SCHEMA_PATH) else {
236	            return UnixSocketState::default();
237	        };
238	        let Ok(catalog) = simd_json::to_owned_value(&mut bytes) else {
239	            return UnixSocketState::default();
240	        };
241	        let Some(state) = catalog
242	            .get("unix_socket")
243	            .and_then(|versions| versions.as_array())
244	            .and_then(|versions| versions.last())
245	            .and_then(|schema| schema.get("example"))
246	        else {
247	            return UnixSocketState::default();
248	        };
249	        simd_json::serde::from_owned_value::<UnixSocketState>(state.clone()).unwrap_or_default()
250	    }
251	
252	    /// Bind a single endpoint when no shared transport exists. If the shared
253	    /// socket is already present, it is owned by the gRPC bridge and this plugin
254	    /// only registers the endpoint metadata.
255	    fn ensure_bound(
256	        active: &mut HashMap<String, UnixListener>,
257	        endpoint: &SocketEndpoint,
258	    ) -> Result<bool> {
259	        if active.contains_key(&endpoint.path) {
260	            return Ok(false);
261	        }
262	        if let Some(parent) = Path::new(&endpoint.path).parent() {
263	            std::fs::create_dir_all(parent)?;
264	        }
265	        if Path::new(&endpoint.path).exists() {
266	            info!(
267	                socket = %endpoint.path,
268	                name = %endpoint.name,
269	                ports = ?endpoint.ports,
270	                protocol = %endpoint.protocol,
271	                "registered unix socket endpoint on existing shared transport"
272	            );
273	            return Ok(false);
274	        }
275	        let listener = UnixListener::bind(&endpoint.path)?;
276	        listener.set_nonblocking(true)?;
277	        active.insert(endpoint.path.clone(), listener);
278	        info!(
279	            socket = %endpoint.path,
280	            name = %endpoint.name,
281	            ports = ?endpoint.ports,
282	            protocol = %endpoint.protocol,
283	            "bound unix socket endpoint"
284	        );
285	        Ok(true)
286	    }
287	
288	    /// Drop a listener and unlink its socket file. Returns `true` when removed.
289	    fn unbind(active: &mut HashMap<String, UnixListener>, path: &str) -> bool {
290	        if active.remove(path).is_some() {
291	            if let Err(error) = std::fs::remove_file(path) {
292	                warn!(socket = %path, %error, "failed to unlink unix socket file");
293	            }
294	            true
295	        } else {
296	            false
297	        }
298	    }
299	
300	    /// Reconcile the live listeners to exactly the supplied desired set.
301	    fn reconcile(&self, desired: &UnixSocketState) -> ApplyResult {
302	        let mut active = self.active.lock();
303	        let mut changes_applied = Vec::new();
304	        let mut errors = Vec::new();
305	
306	        let wanted: HashSet<String> = desired.sockets.iter().map(|s| s.path.clone()).collect();
307	
308	        for endpoint in &desired.sockets {
309	            match Self::ensure_bound(&mut active, endpoint) {
310	                Ok(true) => changes_applied.push(format!(
311	                    "created socket {} (name {}, ports {:?}, {})",
312	                    endpoint.path, endpoint.name, endpoint.ports, endpoint.protocol
313	                )),
314	                Ok(false) => {}
315	                Err(error) => errors.push(format!(
316	                    "failed to create socket {}: {}",
317	                    endpoint.path, error
318	                )),
319	            }
320	        }
321	
322	        let stale: Vec<String> = active
323	            .keys()
324	            .filter(|path| !wanted.contains(*path))
325	            .cloned()
326	            .collect();
327	        for path in stale {
328	            if Self::unbind(&mut active, &path) {
329	                changes_applied.push(format!("removed socket {}", path));
330	            }
331	        }
332	
333	        ApplyResult {
334	            success: errors.is_empty(),
335	            changes_applied,
336	            errors,
337	            checkpoint: None,
338	        }
339	    }
340	
341	    /// `createunixsocket --name <name> --port <csv>` — register a container/service
342	    /// against the single shared `container.sock`.
343	    ///
344	    /// Pure transport, no OVS: the shared socket is bound once; `name` is the
345	    /// identity/demux tag (gemma emits it into the xray config) and `ports` are
346	    /// recorded backend metadata only. tonic-web distinguishes single vs multi
347	    /// protocol and demuxes by gRPC server reflection, so the plugin neither
348	    /// opens these ports nor maps them — OSCAL rule-enforcement routing lives in
349	    /// the separate OpenFlow/policy layer, not in the socket.
350	    pub fn create_unix_socket(&self, name: impl Into<String>, ports: Vec<u16>) -> ApplyResult {
351	        let endpoint = SocketEndpoint {
352	            name: name.into(),
353	            path: SHARED_CONTAINER_SOCKET.to_string(),
354	            ports,
355	            protocol: default_protocol(),
356	            label: String::new(),
357	        };
358	        let mut active = self.active.lock();
359	        match Self::ensure_bound(&mut active, &endpoint) {
360	            Ok(_) => ApplyResult {
361	                success: true,
362	                changes_applied: vec![format!(
363	                    "registered '{}' on shared socket {} (ports {:?})",
364	                    endpoint.name, endpoint.path, endpoint.ports
365	                )],
366	                errors: vec![],
367	                checkpoint: None,
368	            },
369	            Err(error) => ApplyResult {
370	                success: false,
371	                changes_applied: vec![],
372	                errors: vec![format!(
373	                    "createunixsocket '{}' failed: {}",
374	                    endpoint.name, error
375	                )],
376	                checkpoint: None,
377	            },
378	        }
379	    }
380	}
