398	    fn schema(&self) -> Option<op_state_store::PluginSchema> {
399	        let mut schema = unix_socket_schema_derived();
400	        super::common::oscal::ensure_category_metadata_fields(&mut schema);
401	        Some(schema)
402	    }
403	
404	    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
405	        // No diff loop: the schema-declared state is authoritative and applied
406	        // wholesale by `apply_state`.
407	        Ok(StateDiff {
408	            plugin: self.name().to_string(),
409	            actions: vec![],
410	            metadata: DiffMetadata {
411	                timestamp: chrono::Utc::now().timestamp(),
412	                current_hash: "schema".to_string(),
413	                desired_hash: "schema".to_string(),
414	            },
415	        })
416	    }
417	
418	    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
419	        // Reconcile the live unix sockets to exactly the schema-declared set.
420	        let desired = Self::read_desired();
421	        Ok(self.reconcile(&desired))
422	    }
423	
424	    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
425	        let desired = Self::read_desired();
426	        let active = self.active.lock();
427	        let satisfied = desired.sockets.iter().all(|endpoint| {
428	            active.contains_key(&endpoint.path) && Path::new(&endpoint.path).exists()
429	        });
430	        Ok(satisfied)
431	    }
432	
433	    async fn create_checkpoint(&self) -> Result<Checkpoint> {
434	        Ok(Checkpoint {
435	            id: uuid::Uuid::new_v4().to_string(),
436	            plugin: self.name().to_string(),
437	            timestamp: chrono::Utc::now().timestamp(),
438	            state_snapshot: simd_json::serde::to_owned_value(Self::read_desired())?,
439	            backend_checkpoint: None,
440	        })
441	    }
442	
443	    async fn rollback(&self, checkpoint: &Checkpoint) -> Result<()> {
444	        let snapshot = simd_json::serde::from_owned_value::<UnixSocketState>(
445	            checkpoint.state_snapshot.clone(),
446	        )
447	        .unwrap_or_default();
448	        self.reconcile(&snapshot);
449	        Ok(())
450	    }
451	
452	    fn capabilities(&self) -> PluginCapabilities {
453	        PluginCapabilities {
454	            supports_rollback: true,
455	            supports_checkpoints: true,
456	            supports_verification: true,
457	            atomic_operations: false,
458	        }
459	    }
460	}
