155	    /// Whether a Voyage API key is present in the environment — the cloud
156	    /// provider's notion of reachability (it has no list/health endpoint).
157	    fn voyage_key_present() -> bool {
158	        [
159	            "COGNITIVE_MCP_VOYAGE_API_KEY",
160	            "VOYAGE_API_KEY",
161	            "VOYAGE_API_KEY_RUST",
162	        ]
163	        .iter()
164	        .any(|k| std::env::var(k).map(|v| !v.is_empty()).unwrap_or(false))
165	    }
