167	    /// Configuration portion of the state, sourced from the environment.
168	    /// `status`/`available_models`/`model_digest` are observed and filled in by
169	    /// the live query. No active model is hardcoded: an explicit override wins,
170	    /// then the provider-specific env, else empty (resolved in `live_state`).
171	    fn config_state() -> EmbeddingModelState {
172	        EmbeddingModelState {
173	            provider: Self::env_or("EMBEDDING_PROVIDER", "voyage"),
174	            model_id: std::env::var("EMBEDDING_MODEL_ID")
175	                .or_else(|_| std::env::var("COGNITIVE_MCP_VOYAGE_MODEL"))
176	                .or_else(|_| std::env::var("VOYAGE_MODEL"))
177	                .unwrap_or_default(),
178	            endpoint: Self::env_or("EMBEDDING_ENDPOINT", "https://api.voyageai.com/v1/embeddings"),
179	            dimensions: Self::env_u32("EMBEDDING_DIMENSIONS", VoyageModel::SHARED_EMBEDDING_DIMS),
180	            status: "offline".to_string(),
181	            available_models: Vec::new(),
182	            model_digest: String::new(),
183	        }
184	    }
