186	    /// Query an Ollama-compatible provider (`/api/tags`) for its embedding models
187	    /// and their content digests. Returns `None` if unreachable or unparseable.
188	    async fn fetch_ollama_models(endpoint: &str) -> Option<Vec<(String, String)>> {
189	        let url = format!("{}/api/tags", endpoint.trim_end_matches('/'));
190	        let client = reqwest::Client::builder()
191	            .timeout(Duration::from_secs(2))
192	            .build()
193	            .ok()?;
194	        let body = client.get(&url).send().await.ok()?.text().await.ok()?;
195	        let parsed: serde_json::Value = serde_json::from_str(&body).ok()?;
196	        let models = parsed.get("models").and_then(serde_json::Value::as_array)?;
197	        Some(
198	            models
199	                .iter()
200	                .filter_map(|m| {
201	                    let name = m.get("name").and_then(serde_json::Value::as_str)?;
202	                    let digest = m
203	                        .get("digest")
204	                        .and_then(serde_json::Value::as_str)
205	                        .unwrap_or_default();
206	                    Some((name.to_string(), digest.to_string()))
207	                })
208	                .collect(),
209	        )
210	    }
211	
212	    /// Compose the live observed state. Config comes from the environment; the
213	    /// active model / reachability is a lookup to the provider — never a
214	    /// hardcoded active model. Ollama enumerates and resolves a model + digest;
215	    /// Voyage (and other cloud providers) are reachable iff an API key is present
216	    /// and keep the config-driven model with no enumerable catalog.
217	    async fn live_state() -> EmbeddingModelState {
218	        let mut state = Self::config_state();
219	        match state.provider.as_str() {
220	            "ollama" => {
221	                if let Some(models) = Self::fetch_ollama_models(&state.endpoint).await {
222	                    state.status = "online".to_string();
223	                    if state.model_id.is_empty() {
224	                        state.model_id = models
225	                            .first()
226	                            .map(|(name, _)| name.clone())
227	                            .unwrap_or_default();
228	                    }
229	                    if let Some((_, digest)) =
230	                        models.iter().find(|(name, _)| name == &state.model_id)
231	                    {
232	                        state.model_digest = digest.clone();
233	                    }
234	                    state.available_models = models.into_iter().map(|(name, _)| name).collect();
235	                }
236	            }
237	            // Voyage and other cloud providers: no list endpoint. Reachable iff
238	            // an API key is present; the model is config-driven and the catalog
239	            // is not enumerable, so available_models stays observed-empty.
240	            _ => {
241	                if Self::voyage_key_present() {
242	                    state.status = "online".to_string();
243	                    // Known Voyage catalog (the cloud API has no list endpoint):
244	                    // the shared-space trio. This is the enumerable catalog, not
245	                    // an active-model default.
246	                    state.available_models = VoyageModel::SHARED_SPACE
247	                        .iter()
248	                        .map(|m| m.model_id().to_string())
249	                        .collect();
250	                }
251	            }
252	        }
253	        state
254	    }
255	}
