229	impl CodeFilter {
230	    fn qdrant_filter(&self) -> Option<Filter> {
231	        let mut conds: Vec<Condition> = Vec::new();
232	        if let Some(repo) = &self.repo {
233	            conds.push(Condition::matches("repo", repo.clone()));
234	        }
235	        if let Some(lang) = &self.language {
236	            conds.push(Condition::matches("language", lang.clone()));
237	        }
238	        if let Some(ft) = &self.file_type {
239	            conds.push(Condition::matches("file_type", ft.clone()));
240	        }
241	        if conds.is_empty() {
242	            None
243	        } else {
244	            Some(Filter::must(conds))
245	        }
246	    }
247	
248	    fn post_matches(&self, r: &RagResult) -> bool {
249	        if self.exclude_tests && r.is_test {
250	            return false;
251	        }
252	        if let Some(p) = &self.path_contains {
253	            if !r.file_path.to_lowercase().contains(&p.to_lowercase()) {
254	                return false;
255	            }
256	        }
257	        if let Some(s) = &self.symbol_contains {
258	            let needle = s.to_lowercase();
259	            let hit = r
260	                .symbols
261	                .iter()
262	                .any(|sym| sym.to_lowercase().contains(&needle))
263	                || r.file_path.to_lowercase().contains(&needle);
264	            if !hit {
265	                return false;
266	            }
267	        }
268	        true
269	    }
270	}
