317	    /// Ingest a single repomix file from the zip into Qdrant.
318	    #[tracing::instrument(skip(self, zip_path), fields(entry_name, collection))]
319	    pub async fn ingest_repomix_entry(
320	        &self,
321	        zip_path: &Path,
322	        entry_name: &str,
323	        collection: &str,
324	    ) -> Result<IngestStats> {
325	        self.ensure_collection(collection).await?;
326	
327	        let repo = repo_name_from_entry(entry_name);
328	        info!(repo = %repo, entry = %entry_name, "Ingesting repomix entry");
329	
330	        let file = std::fs::File::open(zip_path)?;
331	        let mut archive = zip::ZipArchive::new(file)?;
332	
333	        let entry_idx = (0..archive.len())
334	            .find(|&i| {
335	                archive
336	                    .by_index(i)
337	                    .map(|e| e.name().to_string())
338	                    .ok()
339	                    .as_deref()
340	                    == Some(entry_name)
341	            })
342	            .with_context(|| format!("Entry '{entry_name}' not found in zip"))?;
343	
344	        let entry = archive.by_index(entry_idx)?;
345	        let reader = BufReader::new(entry);
346	
347	        let mut stats = IngestStats::default();
348	        let mut batch: Vec<PointStruct> = Vec::new();
349	
350	        for chunk in parse_and_chunk(reader, &repo) {
351	            stats.files_parsed += 1;
352	            let total = chunk.total_chunks;
353	            stats.chunks_created += total;
354	
355	            // Embed
356	            let vector = match self.embed_document(&chunk.embed_text).await {
357	                Ok(v) => v,
358	                Err(e) => {
359	                    warn!(file = %chunk.file_path, error = %e, "Embed failed, skipping chunk");
360	                    stats.errors += 1;
361	                    continue;
362	                }
363	            };
364	
365	            // Build Qdrant payload with all metadata for hover display
366	            let payload: Payload = serde_json::json!({
367	                "repo":          chunk.repo,
368	                "file_path":     chunk.file_path,
369	                "language":      chunk.meta.language,
370	                "file_type":     chunk.meta.file_type.as_str(),
371	                "symbols":       chunk.meta.symbols,
372	                "doc_comments":  chunk.meta.doc_comments,
373	                "imports":       chunk.meta.imports,
374	                "tags":          chunk.meta.tags,
375	                "is_test":       chunk.meta.is_test,
376	                "line_start":    chunk.line_start,
377	                "line_end":      chunk.line_end,
378	                "chunk_index":   chunk.chunk_index,
379	                "total_chunks":  chunk.total_chunks,
380	                "content":       chunk.content,
381	                "content_hash":  chunk.content_hash,
382	            })
383	            .try_into()
384	            .context("Failed to build payload")?;
385	
386	            // Use content hash as stable point ID (dedup)
387	            batch.push(PointStruct::new(
388	                stable_uuid(&chunk.content_hash),
389	                vector,
390	                payload,
391	            ));
392	
393	            if batch.len() >= VOYAGE_BATCH {
394	                self.flush_batch(collection, &mut batch, &mut stats).await;
395	                tokio::time::sleep(Duration::from_millis(VOYAGE_RATE_DELAY_MS)).await;
396	            }
397	        }
398	
399	        if !batch.is_empty() {
400	            self.flush_batch(collection, &mut batch, &mut stats).await;
401	        }
402	
403	        info!(
404	            repo = %repo,
405	            files = stats.files_parsed,
406	            chunks = stats.chunks_created,
407	            upserted = stats.chunks_upserted,
408	            "Ingest complete"
409	        );
410	
411	        Ok(stats)
412	    }
