501	    /// Fused retrieval across compatible collections. The query is embedded
502	    /// once, then reused for each collection to keep completion requests cheap.
503	    pub async fn query_fused_collections(
504	        &self,
505	        collections: &[String],
506	        query_text: &str,
507	        limit: u64,
508	        fetch_limit: u64,
509	        filter: &CodeFilter,
510	    ) -> Result<Vec<RagResult>> {
511	        let vector = self.embed_query(query_text).await?;
512	        let mut all = Vec::new();
513	
514	        for collection in collections {
515	            match self
516	                .query_fused_with_vector(
517	                    collection,
518	                    query_text,
519	                    limit,
520	                    fetch_limit,
521	                    filter,
522	                    &vector,
523	                )
524	                .await
525	            {
526	                Ok(mut results) => all.append(&mut results),
527	                Err(err) => warn!(
528	                    collection = %collection,
529	                    error = %err,
530	                    "Code-RAG collection search failed"
531	                ),
532	            }
533	        }
534	
535	        all.sort_by(|a, b| {
536	            b.score
537	                .partial_cmp(&a.score)
538	                .unwrap_or(std::cmp::Ordering::Equal)
539	        });
540	        dedupe_results_by_file(&mut all);
541	        all.truncate(limit as usize);
542	        Ok(all)
543	    }
