545	    async fn query_fused_with_vector(
546	        &self,
547	        collection: &str,
548	        query_text: &str,
549	        limit: u64,
550	        fetch_limit: u64,
551	        filter: &CodeFilter,
552	        vector: &[f32],
553	    ) -> Result<Vec<RagResult>> {
554	        self.ensure_collection(collection).await?;
555	        let fetch = fetch_limit.clamp(limit, 100);
556	
557	        let mut builder =
558	            SearchPointsBuilder::new(collection, vector.to_vec(), fetch).with_payload(true);
559	        if let Some(f) = filter.qdrant_filter() {
560	            builder = builder.filter(f);
561	        }
562	
563	        let response = self.qdrant.search_points(builder).await?;
564	
565	        let terms: Vec<String> = query_text
566	            .to_lowercase()
567	            .split(|c: char| !c.is_alphanumeric())
568	            .filter(|t| t.len() > 2)
569	            .map(String::from)
570	            .collect();
571	
572	        let mut best: HashMap<String, RagResult> = HashMap::new();
573	        for pt in response.result {
574	            let mut r = point_to_result(pt);
575	            r.retrieval_collection = collection.to_string();
576	            if !filter.post_matches(&r) {
577	                continue;
578	            }
579	
580	            // Lexical/symbol boost on top of the cosine score.
581	            let mut boost = 0.0f32;
582	            let sym = r.symbols.join(" ").to_lowercase();
583	            let path = r.file_path.to_lowercase();
584	            for t in &terms {
585	                if sym.contains(t) {
586	                    boost += 0.05;
587	                }
588	                if path.contains(t) {
589	                    boost += 0.03;
590	                }
591	            }
592	            r.score += boost.min(0.25);
593	
594	            best.entry(r.file_path.clone())
595	                .and_modify(|e| {
596	                    if r.score > e.score {
597	                        *e = r.clone();
598	                    }
599	                })
600	                .or_insert(r);
601	        }
602	
603	        let mut results: Vec<RagResult> = best.into_values().collect();
604	        results.sort_by(|a, b| {
605	            b.score
606	                .partial_cmp(&a.score)
607	                .unwrap_or(std::cmp::Ordering::Equal)
608	        });
609	        results.truncate(limit as usize);
610	        Ok(results)
611	    }
