613	    /// Index a single in-memory source file (live workspace indexing).
614	    ///
615	    /// Unlike `ingest_repomix_entry`, this takes raw file content directly so a
616	    /// changed buffer can be re-indexed without a repomix zip. Enrichment,
617	    /// chunking, embedding, and upsert are identical to the repomix path.
618	    /// subid: `src.software.workspace.index@v1`
619	    #[tracing::instrument(skip(self, content), fields(repo, file_path, collection))]
620	    pub async fn ingest_source_text(
621	        &self,
622	        repo: &str,
623	        file_path: &str,
624	        content: &str,
625	        collection: &str,
626	    ) -> Result<IngestStats> {
627	        self.ensure_collection(collection).await?;
628	
629	        let lines: Vec<String> = content.lines().map(str::to_string).collect();
630	        let meta = enrich(file_path, &lines);
631	        let chunks = build_chunks(repo, file_path, meta, lines);
632	
633	        let mut stats = IngestStats {
634	            files_parsed: 1,
635	            ..Default::default()
636	        };
637	        let mut batch: Vec<PointStruct> = Vec::new();
638	
639	        for chunk in chunks {
640	            stats.chunks_created += 1;
641	
642	            let vector = match self.embed_document(&chunk.embed_text).await {
643	                Ok(v) => v,
644	                Err(e) => {
645	                    warn!(file = %chunk.file_path, error = %e, "Embed failed, skipping chunk");
646	                    stats.errors += 1;
647	                    continue;
648	                }
649	            };
650	
651	            let payload: Payload = serde_json::json!({
652	                "repo":          chunk.repo,
653	                "file_path":     chunk.file_path,
654	                "language":      chunk.meta.language,
655	                "file_type":     chunk.meta.file_type.as_str(),
656	                "symbols":       chunk.meta.symbols,
657	                "doc_comments":  chunk.meta.doc_comments,
658	                "imports":       chunk.meta.imports,
659	                "tags":          chunk.meta.tags,
660	                "is_test":       chunk.meta.is_test,
661	                "line_start":    chunk.line_start,
662	                "line_end":      chunk.line_end,
663	                "chunk_index":   chunk.chunk_index,
664	                "total_chunks":  chunk.total_chunks,
665	                "content":       chunk.content,
666	                "content_hash":  chunk.content_hash,
667	            })
668	            .try_into()
669	            .context("Failed to build payload")?;
670	
671	            batch.push(PointStruct::new(
672	                stable_uuid(&chunk.content_hash),
673	                vector,
674	                payload,
675	            ));
676	
677	            if batch.len() >= VOYAGE_BATCH {
678	                self.flush_batch(collection, &mut batch, &mut stats).await;
679	                tokio::time::sleep(Duration::from_millis(VOYAGE_RATE_DELAY_MS)).await;
680	            }
681	        }
682	
683	        if !batch.is_empty() {
684	            self.flush_batch(collection, &mut batch, &mut stats).await;
685	        }
686	
687	        info!(
688	            repo = %repo,
689	            file = %file_path,
690	            chunks = stats.chunks_created,
691	            upserted = stats.chunks_upserted,
692	            "Live source ingest complete"
693	        );
694	
695	        Ok(stats)
696	    }
