873	
874	/// Stream-parse a repomix file and yield enriched, chunked entries.
875	/// Never loads the whole file into memory.
876	fn parse_and_chunk(reader: impl BufRead, repo: &str) -> impl Iterator<Item = Chunk> {
877	    let repo = repo.to_string();
878	    let mut lines_iter = reader.lines();
879	    let mut pending: Option<(String, Vec<String>, usize)> = None; // (path, lines, start_lineno)
880	    let mut output: Vec<Chunk> = Vec::new();
881	    let mut file_count = 0usize;
882	
883	    // State machine: collect lines between <file path="..."> and </file>
884	    while let Some(Ok(line)) = lines_iter.next() {
885	        file_count += 1;
886	
887	        if let Some(path) = extract_file_path(&line) {
888	            pending = Some((path, Vec::new(), file_count));
889	            continue;
890	        }
891	
892	        if line.trim() == "</file>" {
893	            if let Some((path, content_lines, _start)) = pending.take() {
894	                let meta = enrich(&path, &content_lines);
895	                let chunks = build_chunks(&repo, &path, meta, content_lines);
896	                output.extend(chunks);
897	            }
898	            continue;
899	        }
900	
901	        if let Some((_, ref mut lines, _)) = pending {
902	            lines.push(line);
903	        }
904	    }
905	
906	    output.into_iter()
907	}
908	
909	fn extract_file_path(line: &str) -> Option<String> {
910	    let trimmed = line.trim();
911	    if !trimmed.starts_with("<file path=\"") {
912	        return None;
913	    }
914	    let rest = trimmed.strip_prefix("<file path=\"")?;
915	    let end = rest.find('"')?;
916	    Some(rest[..end].to_string())
917	}
