921	fn enrich(file_path: &str, lines: &[String]) -> FileMeta {
922	    let language = detect_language(file_path);
923	    let file_type = classify_file(file_path, lines);
924	    let is_test = file_type == FileType::Test
925	        || lines
926	            .iter()
927	            .any(|l| l.contains("#[test]") || l.contains("#[cfg(test)]"));
928	
929	    let (symbols, doc_comments, imports) = match language {
930	        "rust" => extract_rust(lines),
931	        "typescript" | "javascript" => extract_ts(lines),
932	        "python" => extract_python(lines),
933	        "go" => extract_go(lines),
934	        _ => (vec![], vec![], vec![]),
935	    };
936	
937	    let tags = auto_tags(file_path, &symbols, &imports, language);
938	
939	    FileMeta {
940	        language,
941	        file_type,
942	        symbols,
943	        doc_comments,
944	        imports,
945	        tags,
946	        is_test,
947	    }
948	}
