960	        "yaml" | "yml" => "yaml",
961	        "json" => "json",
962	        "md" | "mdx" => "markdown",
963	        "sh" | "bash" => "shell",
964	        "c" | "h" => "c",
965	        "cpp" | "cc" | "cxx" | "hpp" => "cpp",
