973	fn classify_file(path: &str, lines: &[String]) -> FileType {
974	    let lower = path.to_lowercase();
975	    if lower.contains("test") || lower.contains("spec") || lower.ends_with("_test.rs") {
976	        return FileType::Test;
977	    }
978	    if lower.ends_with("cargo.toml")
979	        || lower.ends_with("package.json")
980	        || lower.ends_with("pyproject.toml")
981	        || lower.ends_with("go.mod")
982	        || lower.ends_with("build.rs")
983	        || lower.ends_with("makefile")
984	    {
985	        return FileType::Build;
986	    }
987	    if lower.ends_with(".md") || lower.ends_with(".rst") || lower.ends_with(".txt") {
988	        return FileType::Docs;
989	    }
990	    if lower.ends_with(".toml")
991	        || lower.ends_with(".yaml")
992	        || lower.ends_with(".yml")
993	        || lower.ends_with(".json")
994	        || lower.ends_with(".env")
995	    {
996	        return FileType::Config;
997	    }
998	    if lines
999	        .iter()
1000	        .any(|l| l.contains("#[cfg(test)]") || l.contains("#[test]"))
1001	    {
1002	        return FileType::Test;
1003	    }
1004	    FileType::Source
1005	}
