1007	// Rust symbol extraction
1008	fn extract_rust(lines: &[String]) -> (Vec<String>, Vec<String>, Vec<String>) {
1009	    static RE_ITEM: OnceLock<Regex> = OnceLock::new();
1010	    static RE_USE: OnceLock<Regex> = OnceLock::new();
1011	
1012	    let re_item = RE_ITEM.get_or_init(|| {
1013	        Regex::new(
1014	            r"^\s*pub(?:\(crate\))?\s+(fn|struct|enum|trait|type|mod|const|static|impl)\s+(\w+)",
1015	        )
1016	        .expect("static regex pattern is valid")
1017	    });
1018	    let re_use = RE_USE.get_or_init(|| {
1019	        Regex::new(r"^\s*use\s+([\w::{}, ]+);").expect("static regex pattern is valid")
1020	    });
1021	
1022	    let mut symbols = Vec::new();
1023	    let mut doc_comments = Vec::new();
1024	    let mut imports = Vec::new();
1025	    let mut pending_doc: Vec<String> = Vec::new();
1026	
1027	    for line in lines {
1028	        let trimmed = line.trim();
1029	
1030	        if trimmed.starts_with("///") || trimmed.starts_with("//!") {
1031	            let doc = trimmed.trim_start_matches('/').trim().to_string();
1032	            if !doc.is_empty() {
1033	                pending_doc.push(doc);
1034	            }
1035	            continue;
1036	        }
1037	
1038	        if let Some(caps) = re_item.captures(trimmed) {
1039	            let kind = caps.get(1).map(|m| m.as_str()).unwrap_or("");
1040	            let name = caps.get(2).map(|m| m.as_str()).unwrap_or("");
1041	            symbols.push(format!("{kind} {name}"));
1042	            if !pending_doc.is_empty() {
1043	                doc_comments.push(pending_doc.join(" "));
1044	                pending_doc.clear();
1045	            }
1046	            continue;
1047	        }
1048	
1049	        if let Some(caps) = re_use.captures(trimmed) {
1050	            let import = caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string();
1051	            // Only keep top-level crate (first segment)
1052	            let top = import.split("::").next().unwrap_or(&import);
1053	            let top = top.trim_matches('{').trim().to_string();
1054	            if !top.is_empty() && !imports.contains(&top) {
1055	                imports.push(top);
1056	            }
1057	            continue;
1058	        }
1059	
1060	        pending_doc.clear();
1061	    }
1062	
1063	    // Cap to avoid huge payloads
1064	    symbols.truncate(40);
1065	    doc_comments.truncate(10);
1066	    imports.truncate(30);
1067	
1068	    (symbols, doc_comments, imports)
1069	}
