1071	fn extract_ts(lines: &[String]) -> (Vec<String>, Vec<String>, Vec<String>) {
1072	    static RE_EXPORT: OnceLock<Regex> = OnceLock::new();
1073	    static RE_IMPORT: OnceLock<Regex> = OnceLock::new();
1074	
1075	    let re_export = RE_EXPORT.get_or_init(|| {
1076	        Regex::new(r"^export\s+(?:default\s+)?(?:async\s+)?(?:function|class|interface|type|const|enum)\s+(\w+)").expect("static regex pattern is valid")
1077	    });
1078	    let re_import = RE_IMPORT.get_or_init(|| {
1079	        Regex::new(r#"^import\s+.+from\s+['"]([^'"]+)['"]"#).expect("static regex pattern is valid")
1080	    });
1081	
1082	    let mut symbols = Vec::new();
1083	    let mut imports = Vec::new();
1084	    let mut doc_comments = Vec::new();
1085	
1086	    for line in lines {
1087	        let trimmed = line.trim();
1088	        if let Some(caps) = re_export.captures(trimmed) {
1089	            symbols.push(caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string());
1090	        }
1091	        if let Some(caps) = re_import.captures(trimmed) {
1092	            let src = caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string();
1093	            let pkg = src.split('/').next().unwrap_or(&src);
1094	            let pkg = pkg.trim_start_matches('@').to_string();
1095	            if !imports.contains(&pkg) {
1096	                imports.push(pkg);
1097	            }
1098	        }
1099	        if trimmed.starts_with("/**") || trimmed.starts_with("* ") {
1100	            let doc = trimmed.trim_start_matches(['/', '*', ' ']).to_string();
1101	            if !doc.is_empty() {
1102	                doc_comments.push(doc);
1103	            }
1104	        }
1105	    }
1106	
1107	    symbols.truncate(40);
1108	    doc_comments.truncate(10);
1109	    imports.truncate(30);
1110	    (symbols, doc_comments, imports)
1111	}
