1116	
1117	    let re_def = RE_DEF.get_or_init(|| {
1118	        Regex::new(r"^(?:class|def|async def)\s+(\w+)").expect("static regex pattern is valid")
1119	    });
1120	    let re_imp = RE_IMP.get_or_init(|| {
1121	        Regex::new(r"^(?:import|from)\s+([\w.]+)").expect("static regex pattern is valid")
1122	    });
1123	
1124	    let mut symbols = Vec::new();
1125	    let mut imports = Vec::new();
1126	
1127	    for line in lines {
1128	        let trimmed = line.trim();
1129	        if let Some(caps) = re_def.captures(trimmed) {
1130	            symbols.push(caps.get(1).map(|m| m.as_str()).unwrap_or("").to_string());
