1146	fn extract_go(lines: &[String]) -> (Vec<String>, Vec<String>, Vec<String>) {
1147	    static RE_DECL: OnceLock<Regex> = OnceLock::new();
1148	    static RE_IMP: OnceLock<Regex> = OnceLock::new();
1149	
1150	    let re_decl = RE_DECL.get_or_init(|| {
1151	        Regex::new(r"^func\s+(?:\(\w+\s+\*?\w+\)\s+)?(\w+)|^type\s+(\w+)\s+(?:struct|interface)")
1152	            .expect("static regex pattern is valid")
1153	    });
