1155	        .get_or_init(|| Regex::new(r#"^\s+"([^"]+)""#).expect("static regex pattern is valid"));
1156	
1157	    let mut symbols = Vec::new();
1158	    let mut imports = Vec::new();
1159	
1160	    for line in lines {
1161	        let trimmed = line.trim();
1162	        if let Some(caps) = re_decl.captures(trimmed) {
1163	            let name = caps
1164	                .get(1)
1165	                .or_else(|| caps.get(2))
1166	                .map(|m| m.as_str())
1167	                .unwrap_or("")
1168	                .to_string();
1169	            if !name.is_empty() {
1170	                symbols.push(name);
1171	            }
1172	        }
1173	        if let Some(caps) = re_imp.captures(trimmed) {
1174	            let pkg = caps.get(1).map(|m| m.as_str()).unwrap_or("");
1175	            let top = pkg.split('/').next_back().unwrap_or(pkg).to_string();
1176	            if !imports.contains(&top) {
1177	                imports.push(top);
1178	            }
1179	        }
1180	    }
1181	
1182	    symbols.truncate(40);
1183	    imports.truncate(30);
1184	    (symbols, vec![], imports)
1185	}
