1187	fn auto_tags(path: &str, symbols: &[String], imports: &[String], lang: &str) -> Vec<String> {
1188	    let mut tags: Vec<&str> = Vec::new();
1189	
1190	    // Language tag
1191	    tags.push(lang);
1192	
1193	    // Path-based tags
1194	    let lower = path.to_lowercase();
1195	    for keyword in [
1196	        "server", "client", "handler", "router", "auth", "error", "config", "test", "bench",
1197	        "proto", "grpc", "http", "async", "stream", "channel", "database", "cache",
1198	    ] {
1199	        if lower.contains(keyword) {
1200	            tags.push(keyword);
1201	        }
1202	    }
1203	
1204	    // Symbol-based tags
1205	    let sym_text = symbols.join(" ").to_lowercase();
1206	    for keyword in [
1207	        "trait", "impl", "async", "handler", "service", "client", "server", "error", "config",
1208	        "builder", "stream",
1209	    ] {
1210	        if sym_text.contains(keyword) {
1211	            tags.push(keyword);
1212	        }
1213	    }
1214	
1215	    // Import-based tags
1216	    for imp in imports {
1217	        match imp.as_str() {
1218	            "tokio" | "async_std" => tags.push("async"),
1219	            "tonic" | "prost" => tags.push("grpc"),
1220	            "axum" | "hyper" | "actix" | "warp" => tags.push("http"),
1221	            "serde" | "serde_json" => tags.push("serialization"),
1222	            "sqlx" | "diesel" | "sea_orm" => tags.push("database"),
1223	            "tracing" | "log" => tags.push("logging"),
1224	            "anyhow" | "thiserror" => tags.push("error-handling"),
1225	            _ => {}
1226	        }
1227	    }
1228	
1229	    let mut deduped: Vec<String> = Vec::new();
1230	    for t in tags {
1231	        let s = t.to_string();
1232	        if !deduped.contains(&s) {
1233	            deduped.push(s);
1234	        }
1235	    }
1236	    deduped.truncate(20);
1237	    deduped
1238	}
1239	
1240	// ─── chunking ─────────────────────────────────────────────────────────────────
1241	
1242	fn build_chunks(repo: &str, file_path: &str, meta: FileMeta, lines: Vec<String>) -> Vec<Chunk> {
1243	    if lines.is_empty() {
1244	        return vec![];
1245	    }
1246	
1247	    let mut chunks = Vec::new();
1248	    let step = CHUNK_LINES.saturating_sub(OVERLAP_LINES).max(1);
1249	    let total = ((lines.len() as f64) / step as f64).ceil() as usize;
1250	    let total = total.max(1);
1251	
1252	    let mut idx = 0usize;
1253	    let mut chunk_index = 0usize;
1254	    while idx < lines.len() {
1255	        let end = (idx + CHUNK_LINES).min(lines.len());
1256	        let chunk_lines = &lines[idx..end];
1257	        let content = chunk_lines.join("\n");
1258	        let embed_text = build_embed_text(repo, file_path, &meta, &content);
1259	        let content_hash =
1260	            hex_hash(format!("{repo}:{file_path}:{chunk_index}:{content}").as_bytes());
1261	
1262	        chunks.push(Chunk {
1263	            repo: repo.to_string(),
1264	            file_path: file_path.to_string(),
1265	            meta: meta.clone(),
1266	            content,
1267	            embed_text,
1268	            content_hash,
1269	            chunk_index,
1270	            total_chunks: total,
1271	            line_start: idx + 1,
1272	            line_end: end,
1273	        });
1274	
1275	        idx += step;
1276	        chunk_index += 1;
1277	
1278	        if end >= lines.len() {
1279	            break;
1280	        }
1281	    }
1282	
1283	    chunks
1284	}
1285	
1286	/// Build the text that gets embedded — metadata header + content.
1287	/// The header primes the embedding model with structural context.
1288	fn build_embed_text(repo: &str, file_path: &str, meta: &FileMeta, content: &str) -> String {
1289	    let mut header = format!("REPO: {repo}\nFILE: {file_path}\nLANG: {}\n", meta.language);
1290	
1291	    if !meta.symbols.is_empty() {
1292	        header.push_str(&format!("SYMBOLS: {}\n", meta.symbols.join(", ")));
1293	    }
1294	    if let Some(first_doc) = meta.doc_comments.first() {
1295	        header.push_str(&format!("DOCS: {}\n", first_doc));
1296	    }
1297	    if !meta.imports.is_empty() {
1298	        header.push_str(&format!("DEPS: {}\n", meta.imports.join(", ")));
1299	    }
1300	    if !meta.tags.is_empty() {
1301	        header.push_str(&format!("TAGS: {}\n", meta.tags.join(", ")));
1302	    }
1303	    if meta.is_test {
1304	        header.push_str("TYPE: test\n");
1305	    }
1306	
1307	    format!("{header}---\n{content}")
1308	}
1309	
1310	// ─── helpers ──────────────────────────────────────────────────────────────────
1311	
1312	fn repo_name_from_entry(entry_name: &str) -> String {
1313	    // "rust-analyzer-repomix.md" → "rust-analyzer"
1314	    // "google-cloud-rust-repomix-2.md" → "google-cloud-rust"
1315	    let base = entry_name.trim_end_matches(".md").trim_end_matches(".xml");
1316	
1317	    // Strip trailing "-repomix" and any "-N" suffix
1318	    let base = if let Some(pos) = base.rfind("-repomix") {
1319	        &base[..pos]
1320	    } else {
1321	        base
1322	    };
1323	
1324	    base.to_string()
1325	}
1326	
1327	fn hex_hash(data: &[u8]) -> String {
1328	    let mut h = Sha256::new();
1329	    h.update(data);
1330	    hex::encode(h.finalize())
1331	}
1332	
1333	fn stable_uuid(hash: &str) -> String {
1334	    // Use first 32 hex chars of hash to form a UUID-like stable ID
1335	    if hash.len() >= 32 {
1336	        format!(
1337	            "{}-{}-{}-{}-{}",
1338	            &hash[0..8],
1339	            &hash[8..12],
1340	            &hash[12..16],
1341	            &hash[16..20],
1342	            &hash[20..32]
1343	        )
1344	    } else {
1345	        uuid::Uuid::new_v4().to_string()
1346	    }
1347	}
1348	
1349	// ─── Qdrant connection ────────────────────────────────────────────────────────
1350	
1351	/// Build a Qdrant client from environment.
1352	///
1353	/// Connection is always TCP to localhost. When the qdrant container socket is
1354	/// declared via `UNIX_SOCKET_ENDPOINTS` (e.g. `qdrant:/run/qdrant.sock:6334`),
1355	/// xray transparently proxies `127.0.0.1:6334` → container unix socket using
1356	/// its native domain-socket (`"network": "ds"`) outbound — no custom tonic
1357	/// connector needed here.
1358	///
1359	/// Override the URL with `COGNITIVE_MCP_QDRANT_URL`.
1360	pub fn qdrant_client_from_env() -> Result<Qdrant> {
1361	    let url = std::env::var("COGNITIVE_MCP_QDRANT_URL")
1362	        .unwrap_or_else(|_| "http://127.0.0.1:6334".into());
1363	    Qdrant::from_url(&url)
1364	        .build()
1365	        .context("Failed to build Qdrant client")
1366	}
1367	
1368	/// Load the Voyage API key from a secret file when env vars are unset.
1369	///
1370	/// Defaults to `~/.ssh/mongo-voyage`; override with the
1371	/// `COGNITIVE_MCP_VOYAGE_KEY_FILE` env var. The first non-empty line is used
1372	/// (so a key file with a trailing newline or comment lines works).
1373	fn voyage_key_from_file() -> Option<String> {
1374	    let path = std::env::var("COGNITIVE_MCP_VOYAGE_KEY_FILE")
1375	        .ok()
1376	        .map(std::path::PathBuf::from)
1377	        .or_else(|| std::env::var_os("HOME").map(|h| Path::new(&h).join(".ssh/mongo-voyage")))?;
1378	
1379	    let contents = std::fs::read_to_string(&path).ok()?;
1380	    // The creds file may contain multiple credential types (Atlas service
1381	    // account ID/secret, plus a Voyage API key).  We must skip service
1382	    // account lines and pick the actual API key.
1383	    let key = contents
1384	        .lines()
1385	        .map(str::trim)
1386	        .find(|l| {
1387	            !l.is_empty()
1388	                && !l.starts_with('#')
1389	                // skip Atlas service-account tokens
1390	                && !l.starts_with("mdb_sa_id_")
1391	                && !l.starts_with("mdb_sa_sk_")
1392	                // line should look like a Voyage key (MongoDB-hosted or public)
1393	                && (l.starts_with("al-") || l.starts_with("pa-"))
1394	        })?
1395	        .to_string();
1396	
1397	    if key.is_empty() {
1398	        None
1399	    } else {
1400	        info!(path = %path.display(), "Loaded Voyage API key from file");
1401	        Some(key)
1402	    }
1403	}
1404	
1405	/// Determine the correct Voyage endpoint for a given API key.
1406	fn voyage_url_for_key(key: &str) -> &'static str {
1407	    let trimmed = key.trim();
1408	    if trimmed.starts_with("al-") {
1409	        VOYAGE_MONGODB_URL
1410	    } else {
1411	        VOYAGE_PUBLIC_URL
1412	    }
1413	}
1414	
1415	/// Map a scored Qdrant point + payload into a `RagResult`.
1416	fn point_to_result(pt: ScoredPoint) -> RagResult {
1417	    let p = serde_json::to_value(&pt.payload).unwrap_or_default();
1418	    RagResult {
1419	        retrieval_collection: str_field(&p, "retrieval_collection"),
1420	        score: pt.score,
1421	        repo: str_field(&p, "repo"),
1422	        file_path: str_field(&p, "file_path"),
1423	        language: str_field(&p, "language"),
1424	        file_type: str_field(&p, "file_type"),
1425	        symbols: str_arr(&p, "symbols"),
1426	        doc_comments: str_arr(&p, "doc_comments"),
1427	        imports: str_arr(&p, "imports"),
1428	        tags: str_arr(&p, "tags"),
1429	        is_test: p["is_test"].as_bool().unwrap_or(false),
1430	        line_start: p["line_start"].as_i64().unwrap_or(0),
1431	        line_end: p["line_end"].as_i64().unwrap_or(0),
1432	        chunk_index: p["chunk_index"].as_i64().unwrap_or(0),
1433	        total_chunks: p["total_chunks"].as_i64().unwrap_or(1),
1434	        content: str_field(&p, "content"),
1435	    }
1436	}
1437	
1438	fn str_field(v: &serde_json::Value, key: &str) -> String {
1439	    v[key].as_str().unwrap_or("").to_string()
1440	}
1441	
1442	fn str_arr(v: &serde_json::Value, key: &str) -> Vec<String> {
1443	    v[key]
1444	        .as_array()
1445	        .map(|arr| {
1446	            arr.iter()
1447	                .filter_map(|x| x.as_str().map(str::to_string))
1448	                .collect()
1449	        })
1450	        .unwrap_or_default()
1451	}
1452

