		Referrer-Policy "strict-origin-when-cross-origin"
	}

	reverse_proxy http://netmaker:8081
}

# MQ
broker.{$NM_DOMAIN} {
	@ws {
			header Connection *Upgrade*
			header Upgrade websocket
		}
	reverse_proxy @ws mq:8883
}

